import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2020-08-20","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-08-20","date":"2020-08-20T00:00:00.000Z","updated":"2020-08-21T00:00:00.000Z","tags":["Ceph","CRUSH算法","分布式存储","性能优化","研究论文"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-08-20.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-08-20.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Performance_Meeting_2020-08-20.md"};function o(n,e,s,h,p,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了与Ceph性能相关的几个拉取请求，深入探讨了关于CRUSH算法扩展的论文，并对后续行动计划和潜在研究方向进行了讨论。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>拉取请求更新</strong>：</p><ul><li>目前没有新的与性能相关的拉取请求。</li><li>majianpeng提交的一个拉取请求因长时间未被审查而被stale bot关闭。</li><li>majianpeng提交的另一个拉取请求已由adam和会议参与者审查，主要涉及bluerock环境的刷新行为更改。</li></ul></li><li><p><strong>论文讨论</strong>：</p><ul><li>讨论了一篇关于CRUSH算法扩展的论文，旨在解决集群扩展时数据迁移的问题。</li><li>论文通过引入时间维度映射，使得在集群扩展时大部分数据不需要迁移，仅写入新的OSDs。</li><li>论文还讨论了通过层合并来解决潜在的负载平衡问题。</li></ul></li><li><p><strong>论文的局限性和潜在改进</strong>：</p><ul><li>论文的方法不适用于通用对象存储，如RGW。</li><li>引入的时间戳和复杂的管理算法增加了系统的复杂性。</li><li>讨论了是否可以通过改进现有的PG临时机制或引入新的多CRUSH规则方法来简化实现。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续关注和改进现有的PG临时机制。</li><li>考虑实施一种新的多CRUSH规则方法，以简化集群扩展时的数据迁移。</li><li>探索其他可能的改进措施，如QoS机制，以更好地控制后台数据迁移对客户端IO的影响。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>论文提出的方法虽然有其创新之处，但由于其局限性和复杂性，目前不考虑直接实施。</li><li>将重点放在改进现有的PG临时机制和探索新的多CRUSH规则方法上。</li><li>计划定期讨论和阅读新的研究论文，以保持对最新研究动态的关注。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控和改进PG临时机制。</li><li>探索和实施新的多CRUSH规则方法。</li><li>定期组织论文阅读和讨论会，以促进团队对最新研究成果的了解和应用。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了未来的研究方向和行动计划后结束，参与者表示将积极参与后续的研究和开发工作。</p>',11)])])}const u=a(r,[["render",o]]);export{_ as __pageData,u as default};
